trap 'rm -f "$f"' EXIT
cat > "$f" <<'EOF'
package cache_test

import (
	"testing"
	"time"

	"github.com/hatchet-dev/hatchet/internal/cache"
)

func TestWavezBenchLen(t *testing.T) {
	c := cache.NewTTL[string, int]()
	defer c.Stop()
	if got := c.Len(); got != 0 {
		t.Fatalf("empty Len() = %d", got)
	}
	c.Set("a", 1, time.Hour)
	c.Set("b", 2, time.Hour)
	c.Set("gone", 3, time.Nanosecond)
	time.Sleep(20 * time.Millisecond)
	if got := c.Len(); got != 2 {
		t.Fatalf("Len() with one expired = %d, want 2", got)
	}
	c.Remove("a")
	if got := c.Len(); got != 1 {
		t.Fatalf("Len() after Remove = %d, want 1", got)
	}
}
EOF
go test -count=1 ./internal/cache/

