package main

import (
	"strings"
	"testing"
)

func TestWavezBenchRedactsGitLab(t *testing.T) {
	for _, in := range []string{
		"remote rejected glpat-AbCdEfGhIjKlMnOpQrSt for this push",
		"glpat-a1_b2-c3d4e5f6g7h8i9j0kLmN",
	} {
		got := redactSecrets(in)
		if strings.Contains(got, "AbCdEfGhIjKlMnOpQrSt") || strings.Contains(got, "a1_b2-c3d4e5f6g7h8i9j0kLmN") {
			t.Errorf("redactSecrets(%q) = %q", in, got)
		}
	}
	if got := redactSecrets("plain text stays"); got != "plain text stays" {
		t.Errorf("plain text changed to %q", got)
	}
}
EOF
