cat > "$f" <<'EOT'
package validator

import (
	"strings"
	"testing"
)

func TestWavezBenchPasswordCountsCharacters(t *testing.T) {
	long := strings.Repeat("あ", 30) + "aA1"
	if !passwordValidation(long) {
		t.Errorf("33 characters in %d bytes was refused", len(long))
	}
	if short := "あaA1"; passwordValidation(short) {
		t.Errorf("4 characters in %d bytes was accepted", len(short))
	}
	if !passwordValidation("Abcdefg1") || passwordValidation("Abcdef1") {
		t.Error("the 8-character floor moved")
	}
	if !passwordValidation(strings.Repeat("a", 62)+"A1") || passwordValidation(strings.Repeat("a", 63)+"A1") {
		t.Error("the 64-character ceiling moved")
	}
}
EOT
go test -count=1 ./pkg/validator/

