package retry

import (
	"net/http"
	"testing"
	"time"
)

func TestWavezBenchRetryAfterPadding(t *testing.T) {
	now := time.Unix(0, 0).UTC()
	date := now.Add(3 * time.Second).Format(http.TimeFormat)
	for in, want := range map[string]time.Duration{
		" 2": 2 * time.Second, "2 ": 2 * time.Second, "\t2\t": 2 * time.Second, "2": 2 * time.Second,
		" " + date + " ": 3 * time.Second,
	} {
		got, ok := parseRetryAfter(in, now, restMaxRetryAfter)
		if !ok || got != want {
			t.Errorf("parseRetryAfter(%q) = %v, %v, want %v", in, got, ok, want)
		}
	}
	for _, in := range []string{"", "   ", "2 s", "-1", " 10 "} {
		if got, ok := parseRetryAfter(in, now, restMaxRetryAfter); ok {
			t.Errorf("parseRetryAfter(%q) = %v, want it refused", in, got)
		}
	}
}
EOT
