package datautils

import (
	"reflect"
	"testing"
)

func TestWavezBenchRenderNull(t *testing.T) {
	data := map[string]interface{}{"name": "hatchet"}
	input := map[string]interface{}{
		"note": nil, "greeting": "hi {{.name}}", "count": 3,
		"nested": map[string]interface{}{"inner": nil, "who": "{{.name}}"},
	}
	want := map[string]interface{}{
		"note": nil, "greeting": "hi hatchet", "count": 3,
		"nested": map[string]interface{}{"inner": nil, "who": "hatchet"},
	}
	got, err := RenderTemplateFields(data, input)
	if err != nil || !reflect.DeepEqual(got, want) {
		t.Errorf("got %#v, %v", got, err)
	}
	if _, err := RenderTemplateFields(data, map[string]interface{}{"bad": map[string]string{"a": "b"}}); err == nil {
		t.Error("a map of another type was accepted")
	}
}
EOT
